#!/usr/bin/env python3
# MONKEYHUB PATCH 10: regenerates
#   android/src/whisper/whisper.cpp/ggml/src/ggml-metal/ggml-metal-embed.c
# the Metal shader source the pods embed (GGML_METAL_EMBED_LIBRARY). This is
# what upstream's CMake does at build time with sed + an .incbin assembly
# file; CocoaPods has no codegen step, so the result is checked in as a C
# string instead. The OS compiles it at runtime (newLibraryWithSource), so
# no Metal toolchain is needed to build the app. Run from the package root
# after updating ggml-metal.metal, ggml-metal-impl.h or ggml-common.h:
#   python3 tool/gen_metal_embed.py
import os

G = 'android/src/whisper/whisper.cpp/ggml/src'
M = os.path.join(G, 'ggml-metal')


def read(path):
    with open(path, encoding='utf-8') as f:
        return f.read()


common = read(os.path.join(G, 'ggml-common.h'))
impl = read(os.path.join(M, 'ggml-metal-impl.h'))
out_lines = []
# Same substitutions as upstream ggml-metal/CMakeLists.txt.
for line in read(os.path.join(M, 'ggml-metal.metal')).splitlines(keepends=True):
    if '__embed_ggml-common.h__' in line:
        out_lines.append(common if common.endswith('\n') else common + '\n')
    elif '#include "ggml-metal-impl.h"' in line:
        out_lines.append(impl if impl.endswith('\n') else impl + '\n')
    else:
        out_lines.append(line)
src = ''.join(out_lines)


def c_line(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\t', '\\t') + '\\n"'


body = '\n'.join(c_line(l) for l in src.split('\n'))
with open(os.path.join(M, 'ggml-metal-embed.c'), 'w', encoding='utf-8') as f:
    f.write('// GENERATED by tool/gen_metal_embed.py (MONKEYHUB PATCH 10). Do not edit.\n'
            '// ggml-metal.metal with ggml-common.h and ggml-metal-impl.h inlined.\n'
            '#if defined(GGML_USE_METAL) && defined(GGML_METAL_EMBED_LIBRARY)\n'
            '#include <stddef.h>\n'
            'const char ggml_metallib_start[] =\n' + body + ';\n'
            'const size_t ggml_metallib_len = sizeof(ggml_metallib_start) - 1;\n'
            '#endif\n')
print('%d bytes of Metal source embedded' % len(src))
